import { LogicWrapper, MakeLogicType, afterMount, kea, key, path, props, reducers } from 'kea'
import { loaders } from 'kea-loaders'

import { serviceAccountsApiKeysList, serviceAccountsRetrieve } from '~/generated/core/api'
import type { ServiceAccountApi, ServiceAccountAPIKeyApi } from '~/generated/core/api.schemas'

export interface ServiceAccountLogicProps {
    organizationId: string
    accountId: string
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface serviceAccountLogicValues {
    account: ServiceAccountApi | null
    accountLoadFailed: boolean
    accountLoading: boolean
    apiKeys: ServiceAccountAPIKeyApi[] | null
    apiKeysLoading: boolean
    keysLoadFailed: boolean
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface serviceAccountLogicActions {
    loadAccount: () => any
    loadAccountFailure: (
        error: string,
        errorObject?: any
    ) => {
        error: string
        errorObject?: any
    }
    loadAccountSuccess: (
        account: ServiceAccountApi,
        payload?: any
    ) => {
        account: ServiceAccountApi
        payload?: any
    }
    loadApiKeys: () => any
    loadApiKeysFailure: (
        error: string,
        errorObject?: any
    ) => {
        error: string
        errorObject?: any
    }
    loadApiKeysSuccess: (
        apiKeys: ServiceAccountAPIKeyApi[],
        payload?: any
    ) => {
        apiKeys: ServiceAccountAPIKeyApi[]
        payload?: any
    }
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface serviceAccountLogicMeta {
    key: string
}

export type serviceAccountLogicType = MakeLogicType<
    serviceAccountLogicValues,
    serviceAccountLogicActions,
    ServiceAccountLogicProps,
    serviceAccountLogicMeta
>

export const serviceAccountLogic: LogicWrapper<serviceAccountLogicType> = kea<serviceAccountLogicType>([
    props({} as ServiceAccountLogicProps),
    key(({ organizationId, accountId }) => `${organizationId}:${accountId}`),
    path((key) => ['scenes', 'settings', 'organization', 'serviceAccounts', 'serviceAccountLogic', key]),
    loaders(({ props }) => ({
        account: [
            null as ServiceAccountApi | null,
            { loadAccount: async () => serviceAccountsRetrieve(props.organizationId, props.accountId) },
        ],
        apiKeys: [
            null as ServiceAccountAPIKeyApi[] | null,
            { loadApiKeys: async () => serviceAccountsApiKeysList(props.organizationId, props.accountId) },
        ],
    })),
    reducers({
        accountLoadFailed: [
            false,
            { loadAccount: () => false, loadAccountSuccess: () => false, loadAccountFailure: () => true },
        ],
        keysLoadFailed: [
            false,
            { loadApiKeys: () => false, loadApiKeysSuccess: () => false, loadApiKeysFailure: () => true },
        ],
    }),
    afterMount(({ actions }) => {
        actions.loadAccount()
        actions.loadApiKeys()
    }),
])
